window.kbPageData["views/entry/k-12c9175d5368fd5d"] = {"key":"entry/k-12c9175d5368fd5d","state":{"route":"entry/k-12c9175d5368fd5d"},"node":{"id":"k-12c9175d5368fd5d","mode":"k","title":"城镇开发边界内地上地下空间统筹（2023年通知）","type":"制度与规则","domain":"公共管理","reading":"","intro":"","priority":100,"aliases":["城镇开发边界内地上与地下空间的规划统筹"],"qs":["江苏 2024 C类 行测#15"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewDoubt":"公开转载与所给D项措辞一致。仍需核对官方原卷或正式答案依据，确认命题是否以D项缺少边界内布局和规划实施条件作为单选A的依据。","reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"原题引文：各地要结合市县国土空间规划编制审批实施","review":{"definition":"原题引文：各地要结合市县国土空间规划编制审批实施","explanation":"A项关于不得擅自突破扩展倍数的表述直接对应通知第一部分。公开试题转载的D项也写作“大力推动城镇地上地下空间复合利用”，但未交代是否依照市县国土空间规划、是否在边界内实施。通知第二部分的规定使合规性取决于这些条件，仅凭D项无法确认合规，也不能认定复合利用本身违背要求。","references":[{"source":"web-9e0c31f3324d0982","location":"第二部分，推动城镇开发边界划定成果精准落地实施","quote":"统筹存量用地和增量用地、地上空间和地下空间"},{"source":"web-fbab594a288ef143","location":"第十九条","quote":"同时废止"},{"source":"web-6d273408178d2c9b","location":"第4页，第15题D项","quote":"某县大力推动城镇地上地下空间复合利用"}],"evidence":"各地要结合市县国土空间规划编制审批实施","disposition":"题内说明","basis":"据原题与所列资料编释。"}},"questions":{"江苏 2024 C类 行测#15":{"paper":"江苏 2024 C类 行测","n":15,"mod":"常识判断","src":["3f1ec77ae8a18519b57e.pdf",3],"asrc":["02d6b49839583bdaf297.pdf",5],"card":"e7c7edb183fdc6becf63ce25","links":[{"id":"k-12c9175d5368fd5d","role":"解题依据","why":"统筹地上和地下空间须结合市县国土空间规划的编制、审批和实施。"}]}},"terms":{},"references":{"web-9e0c31f3324d0982":{"name":"《自然资源部关于做好城镇开发边界管理的通知（试行）》","url":"https://app.www.gov.cn/govdata/gov/202310/11/508110/article.html"},"web-fbab594a288ef143":{"name":"《城镇开发边界管理办法（试行）》","url":"https://zrzy.guizhou.gov.cn/wzgb/zwgk/zfxxgk/fdzdgknr/zcwj/zcfg/202605/t20260511_90160811.html"},"web-6d273408178d2c9b":{"name":"《2024年江苏公务员考试行测试题（C类）》公开转载版","url":"https://www.chinagwy.org/files/20241206160947_16977.pdf"}},"topics":[],"units":{"k-12c9175d5368fd5d":[["江苏 2024 C类 行测#15"]]}};
